INSERT IGNORE INTO store_information (topic, content) VALUES
('website_creator', 'The website was created by SHANMUKH ADITYA.'),
('about', 'Sri Rajeswari Wellness & General Stores has served the local community for approximately 20 years, as reported by the owner in October 2026.'),
('location', 'The store is on Sarpavaram-Panasapadu Road, Kakinada. An exact door number and map pin have not yet been provided; call the store for directions.'),
('contact', 'Phone: 9398643062. Email: srirajeswari1@gmail.com. WhatsApp service has not been confirmed.'),
('services', 'The store offers baby care, cosmetics, human wellness products, pet accessories, pet and veterinary medicines, human medicines from a wide range of companies, and generic medicines at competitive prices. This describes the general range, not a guarantee of any brand or item being in stock. Check the current catalogue or contact the store for a specific item. Medicine suitability and prescription requirements must be checked with the pharmacist; pet treatment questions should go to a veterinarian.'),
('delivery', 'Home delivery is available to Kakinada PIN codes 533005 and 533002. Free home delivery requires an order value of INR 1000 or more (including exactly INR 1000). Delivery time and whether orders below INR 1000 can be delivered for a charge are unconfirmed; call 9398643062 to check. This describes the delivery policy, not a verification that a particular cart qualifies. The website currently checks PIN codes, not GPS distance.'),
('checkout', 'Customers can add products to My Cart, choose Checkout, enter their delivery details, and place an order. The current website supports Cash on Delivery. Staff call to confirm the order. The chatbot cannot place or change orders, access customer orders or contact staff.'),
('hours', 'Opening hours, closing hours and holiday schedules have not yet been provided. Please call 9398643062 to confirm.'),
('returns', 'Return, cancellation and refund rules have not yet been provided. Please contact the store before assuming an item is eligible.'),
('supplement_safety', 'Symptoms alone do not establish a nutrient deficiency. Do not match blurred vision to vitamin A; fatigue or numbness to B12; bruising or bleeding gums to vitamin C; bone pain or fractures to vitamin D/calcium; hair loss to biotin; cramps or insomnia to magnesium; or breathlessness/low haemoglobin to iron. Do not claim vitamin C/zinc treats flu or assume every person over 50 needs an iron-free multivitamin. Refer symptom, pregnancy, child-health and treatment questions to a qualified clinician or pharmacist. A named product can be looked up without endorsing its clinical suitability.'),
('supplement_interactions', 'Important: If you are currently taking prescription medications (especially blood thinners, thyroid medication, or antibiotics), please consult our in-store pharmacist or your physician before starting this supplement to avoid harmful interactions.'),
('supplement_dosage', 'Do not provide a personalised dose. For a supplement already selected with a qualified clinician or pharmacist, follow their directions and the product label. Do not take mega-doses of vitamins A, D, E or K, or minerals such as iron or zinc, without medical supervision. The chatbot must not advise changes to prescribed treatment.');
